import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Grid } from 'lucide-react';

const colors = {
  primary: '#ff3d7f',
  secondary: '#121212',
  secondaryLight: '#212121',
  light: '#ffffff',
  midGray: '#868686',
  accent: '#00dbdd',
};

const ConceptBoard = () => {
  const [conceptArt, setConceptArt] = useState([]);
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const [startDrag, setStartDrag] = useState({ x: 0, y: 0 });
  const boardRef = useRef(null);
  const fileInputRef = useRef(null);

  const handleMouseDown = (e) => {
    if (e.button !== 0) return;
    setDragging(true);
    setStartDrag({ x: e.clientX, y: e.clientY });
  };

  const handleMouseMove = (e) => {
    if (!dragging) return;
    setOffset(prev => ({
      x: prev.x + e.clientX - startDrag.x,
      y: prev.y + e.clientY - startDrag.y
    }));
    setStartDrag({ x: e.clientX, y: e.clientY });
  };

  const handleMouseUp = () => setDragging(false);

  const handleWheel = (e) => {
    e.preventDefault();
    const zoomSpeed = 0.05;
    const newScale = Math.max(0.1, scale - e.deltaY * zoomSpeed);
    setScale(newScale);
  };

  const handleUpload = (e) => {
    const files = e.target.files;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = () => {
        setConceptArt(prev => [...prev, {
          id: Date.now(),
          name: file.name,
          src: reader.result,
          x: 100,
          y: 100,
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  return (
    <div className="min-h-screen bg-[#121212] p-4 flex flex-col items-center">
      <div className="w-full max-w-6xl mb-4 flex justify-between items-center">
        <h1 className="text-white text-2xl font-bold">Concept Board</h1>
        <div className="flex items-center gap-2">
          <button
            onClick={() => fileInputRef.current.click()}
            className="bg-[#00dbdd] text-black font-semibold px-4 py-2 rounded"
          >
            <Upload className="inline w-4 h-4 mr-1" /> Upload
          </button>
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleUpload}
            accept="image/*"
            multiple
            className="hidden"
          />
        </div>
      </div>

      <div
        ref={boardRef}
        className="w-full max-w-6xl h-[70vh] border-2 border-[#00dbdd] rounded-lg overflow-hidden bg-[#1e1e1e] relative"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onWheel={handleWheel}
      >
        <div
          className="absolute"
          style={{
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`,
            transformOrigin: 'top left'
          }}
        >
          {conceptArt.map(art => (
            <img
              key={art.id}
              src={art.src}
              alt={art.name}
              className="absolute rounded border border-[#00dbdd]"
              style={{ left: art.x, top: art.y, width: 200 }}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default ConceptBoard;
